const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const norwegianSeaPoint = ee.Geometry.Point(2.0, 68.0); // A central point in the Norwegian Sea
  const startDate = '2019-06-05';
  const endDate = '2019-06-05'; // Only interested in this specific day

  // Define a larger area to ensure more pixels for context, while still centered on Norwegian Sea.
  // This polygon roughly covers a significant part of the Norwegian Sea.
  const norwegianSeaRegion = ee.Geometry.Polygon(
    [[[-5.0, 60.0], [15.0, 60.0], [15.0, 75.0], [-5.0, 75.0], [-5.0, 60.0]]]
  );

  const bloomThreshold = 1.0; // Chlorophyll-a concentration in mg/m^3 indicating a bloom.
                              // Typical background is <0.5 mg/m^3; blooms can exceed 1-10 mg/m^3.

  // 2. Data Acquisition
  let collection = ee.ImageCollection('MODIS/051/MOLT/L3_CHLA_DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(norwegianSeaRegion);

  // Check collection size
  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No MODIS Aqua chlorophyll-a data found for June 5, 2019, in the Norwegian Sea.");
    console.log("C1");
    return;
  }

  // Get the single image for the day
  let image = collection.first();

  // 3. Processing
  // Select the chlorophyll-a band
  let chlaImage = image.select('chlor_a');

  // Mask out invalid chlorophyll-a values (MODIS often uses fill values or very low values for non-ocean/cloudy areas)
  // Valid chlorophyll-a values are typically positive. Max values can go up to ~60 mg/m^3, though blooms are often less than 20.
  chlaImage = chlaImage.updateMask(chlaImage.gt(0.01).and(chlaImage.lt(50))); // Filter out very low noise and extreme highs

  // Calculate pixel count for valid pixels in the region
  const pixelCountDict = await chlaImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: norwegianSeaRegion,
    scale: 4000, // MODIS resolution is ~4km, use a scale matching or slightly larger
    maxPixels: 1e9
  }).getInfo();

  const validPixels = pixelCountDict ? pixelCountDict['chlor_a'] : 0;

  if (validPixels === 0) {
    console.log(`Image found, but 0 valid pixels remain after masking for region: ${norwegianSeaRegion.toGeoJSON().type}.`);
    console.log("C2");
    return;
  }

  // Calculate the mean chlorophyll-a concentration over the region
  const meanChlaDict = await chlaImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: norwegianSeaRegion,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const meanChla = meanChlaDict ? meanChlaDict['chlor_a'] : null;

  // 4. Validation & Final Answer
  if (meanChla === null || isNaN(meanChla)) {
    console.log("Calculation of mean chlorophyll-a failed (result is null or NaN).");
    console.log("C3");
    return;
  }

  console.log(`Date: ${startDate}`);
  console.log(`Valid Pixels in region: ${validPixels}`);
  console.log(`Mean Chlorophyll-a: ${meanChla.toFixed(2)} mg/m^3`);
  console.log(`Bloom Threshold: > ${bloomThreshold} mg/m^3`);

  if (meanChla > bloomThreshold) {
    console.log("A"); // Yes, blooms were likely visible
  } else {
    console.log("B"); // No, blooms were not prominent
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
